insert into problems (title, slug, description, difficulty, time_limit_sec, examples, test_cases) values (
  $t$Fibonacci Number$t$, 'fibonacci-number', $md$The Fibonacci sequence starts `F(0) = 0`, `F(1) = 1`, and each next term is the sum of the previous two. Print `F(n)`.

**Input**
- A single integer `n` (0 ≤ n ≤ 90)

**Output**
- `F(n)`. It fits in a signed 64-bit integer.$md$, 'easy', 600,
  $j$[{"input": "0", "output": "0"}]$j$::jsonb,
  $j$[{"input":"0\n","expected_output":"0","is_hidden":false},{"input":"1\n","expected_output":"1","is_hidden":true},{"input":"10\n","expected_output":"55","is_hidden":true},{"input":"50\n","expected_output":"12586269025","is_hidden":true},{"input":"90\n","expected_output":"2880067194370816120","is_hidden":true}]$j$::jsonb
) on conflict (slug) do nothing;

insert into problems (title, slug, description, difficulty, time_limit_sec, examples, test_cases) values (
  $t$Prime Check$t$, 'prime-check', $md$Decide whether `n` is a prime number.

**Input**
- A single integer `n` (1 ≤ n ≤ 10^12)

**Output**
- `YES` if `n` is prime, otherwise `NO`.$md$, 'easy', 600,
  $j$[{"input": "1", "output": "NO"}]$j$::jsonb,
  $j$[{"input":"1\n","expected_output":"NO","is_hidden":false},{"input":"2\n","expected_output":"YES","is_hidden":true},{"input":"17\n","expected_output":"YES","is_hidden":true},{"input":"100\n","expected_output":"NO","is_hidden":true},{"input":"999999937\n","expected_output":"YES","is_hidden":true},{"input":"999999999989\n","expected_output":"YES","is_hidden":true},{"input":"999999999991\n","expected_output":"NO","is_hidden":true}]$j$::jsonb
) on conflict (slug) do nothing;

insert into problems (title, slug, description, difficulty, time_limit_sec, examples, test_cases) values (
  $t$Digit Sum$t$, 'digit-sum', $md$Add up the decimal digits of `n`.

**Input**
- A single integer `n` (0 ≤ n ≤ 10^18)

**Output**
- The sum of its digits.$md$, 'easy', 600,
  $j$[{"input": "12345", "output": "15"}]$j$::jsonb,
  $j$[{"input":"12345\n","expected_output":"15","is_hidden":false},{"input":"0\n","expected_output":"0","is_hidden":true},{"input":"999999999999999999\n","expected_output":"162","is_hidden":true},{"input":"100\n","expected_output":"1","is_hidden":true},{"input":"987654321\n","expected_output":"45","is_hidden":true}]$j$::jsonb
) on conflict (slug) do nothing;

insert into problems (title, slug, description, difficulty, time_limit_sec, examples, test_cases) values (
  $t$Greatest Common Divisor$t$, 'greatest-common-divisor', $md$Find the greatest common divisor of two positive integers.

**Input**
- Two integers `a` and `b` (1 ≤ a, b ≤ 10^18) on one line

**Output**
- `gcd(a, b)`$md$, 'easy', 600,
  $j$[{"input": "12 18", "output": "6"}]$j$::jsonb,
  $j$[{"input":"12 18\n","expected_output":"6","is_hidden":false},{"input":"17 5\n","expected_output":"1","is_hidden":true},{"input":"1000000000000 250000000000\n","expected_output":"250000000000","is_hidden":true},{"input":"1 1\n","expected_output":"1","is_hidden":true},{"input":"48 180\n","expected_output":"12","is_hidden":true},{"input":"999999999999999989 999999999999999967\n","expected_output":"1","is_hidden":true}]$j$::jsonb
) on conflict (slug) do nothing;

insert into problems (title, slug, description, difficulty, time_limit_sec, examples, test_cases) values (
  $t$Count Words$t$, 'count-words', $md$Count the words in a line. Words are separated by one or more spaces, and the line may start or end with spaces.

**Input**
