insert into problems (title, slug, description, difficulty, time_limit_sec, examples, test_cases) values (
  $t$Pascal Triangle Row$t$, 'pascal-triangle-row', $md$Rows of Pascal's triangle start with row 0 = `1`. Each inner number is the sum of the two above it. Print row `n`.

**Input**
- A single integer `n` (0 ≤ n ≤ 30)

**Output**
- The numbers of row `n`, separated by spaces.$md$, 'medium', 900,
  $j$[{"input": "0", "output": "1"}]$j$::jsonb,
  $j$[{"input":"0\n","expected_output":"1","is_hidden":false},{"input":"1\n","expected_output":"1 1","is_hidden":true},{"input":"4\n","expected_output":"1 4 6 4 1","is_hidden":true},{"input":"10\n","expected_output":"1 10 45 120 210 252 210 120 45 10 1","is_hidden":true},{"input":"30\n","expected_output":"1 30 435 4060 27405 142506 593775 2035800 5852925 14307150 30045015 54627300 86493225 119759850 145422675 155117520 145422675 119759850 86493225 54627300 30045015 14307150 5852925 2035800 593775 142506 27405 4060 435 30 1","is_hidden":true}]$j$::jsonb
) on conflict (slug) do nothing;

insert into problems (title, slug, description, difficulty, time_limit_sec, examples, test_cases) values (
  $t$Count Primes$t$, 'count-primes', $md$Count the prime numbers that are less than or equal to `n`.

**Input**
- A single integer `n` (1 ≤ n ≤ 1000000)

**Output**
- The number of primes up to `n`.$md$, 'medium', 900,
  $j$[{"input": "10", "output": "4"}]$j$::jsonb,
  $j$[{"input":"10\n","expected_output":"4","is_hidden":false},{"input":"1\n","expected_output":"0","is_hidden":true},{"input":"2\n","expected_output":"1","is_hidden":true},{"input":"100\n","expected_output":"25","is_hidden":true},{"input":"500000\n","expected_output":"41538","is_hidden":true},{"input":"1000000\n","expected_output":"78498","is_hidden":true}]$j$::jsonb
) on conflict (slug) do nothing;

insert into problems (title, slug, description, difficulty, time_limit_sec, examples, test_cases) values (
  $t$Best Time to Buy and Sell$t$, 'best-time-to-buy-and-sell', $md$Given a list of daily prices, choose one day to buy and a later day to sell to maximize profit.

**Input**
- Line 1: `n` days (1 ≤ n ≤ 100000)
- Line 2: `n` prices (1 ≤ price ≤ 10^9)

**Output**
- The maximum profit, or `0` if no profit is possible.$md$, 'medium', 900,
